public String sortString(String s) {
    String result = "";
    while (s.length() > 0) {
        // pick the smallest character
        int smallestIdx = -1;
        char smallest = 'z';
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) < smallest) {
                smallest = s.charAt(i);
                smallestIdx = i;
            }
        }
        result += smallest;

        // remove the picked character from the string
        s = s.substring(0, smallestIdx) + s.substring(smallestIdx + 1);

        // pick the smallest character greater than the last
        int smallestGreaterIdx = -1;
        char smallestGreater = 'z';
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) > result.charAt(result.length() - 1) && s.charAt(i) < smallestGreater) {
                smallestGreater = s.charAt(i);
                smallestGreaterIdx = i;
            }
        }
        if (smallestGreaterIdx == -1) break; // no character greater than the last one
        result += smallestGreater;
        s = s.substring(0, smallestGreaterIdx) + s.substring(smallestGreaterIdx + 1);

        // pick the largest character
        int largestIdx = -1;
        char largest = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) > largest) {
                largest = s.charAt(i);
                largestIdx = i;
            }
        }
        result += largest;

        // remove the picked character from the string
        s = s.substring(0, largestIdx) + s.substring(largestIdx + 1);

        // pick the largest character
        int largestSmallerIdx = -1;
        char largestSmaller = 0;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) < result.charAt(result.length() - 1) && s.charAt(i) > largestSmaller) {
                largestSmaller = s.charAt(i);
                largestSmallerIdx = i;
            }
        }
        if (largestSmallerIdx == -1) break; // no character smaller than the last one
        result += largestSmaller;
        s = s.substring(0, largestSmallerIdx) + s.substring(largestSmallerIdx + 1);
    }
    return result;
}
